// app/components/NewCartModal.tsx
import React from "react";
import { getCarrito, deleteProductFromCart } from "../Data/Cart"; // Importamos las funciones
import styles from '../styles/NewCartModal.module.css'; // Estilos para el modal

// Modificamos el componente para recibir los productos como prop
const NewCartModal = ({
  handleClose,
  products, // Recibimos los productos como prop
}: {
  handleClose: () => void;
  products: { id: number; name: string; price: number; imageUrl: string }[]; // Definimos los tipos de los productos
}) => {
  const cartItems = getCarrito(); // Obtenemos los productos en el carrito

  // Función para obtener los detalles del producto (nombre y precio) desde el arreglo de productos
  const getProductDetails = (code: string) => {
    return products.find((product) => product.id.toString() === code);
  };

  // Calcular el total del carrito
  const total = cartItems.reduce((acc, item) => {
    const product = getProductDetails(item.code);
    if (product) {
      acc += product.price * item.quantity;
    }
    return acc;
  }, 0);

  return (
    <div className={styles.modal}>
      <div className={styles.modalContent}>
        <button onClick={handleClose} className={styles.closeButton}>
          X
        </button>
        <h2>Resumen del Carrito</h2>
        <div className={styles.cartItems}>
          {cartItems.length === 0 ? (
            <p>El carrito está vacío.</p>
          ) : (
            cartItems.map((item) => {
              const product = getProductDetails(item.code);
              return product ? (
                <div key={item.code} className={styles.cartItem}>
                  <p>{product.name} - Cantidad: {item.quantity}</p>
                  <p>Precio: ${product.price} c/u</p>
                  <p>Total: ${product.price * item.quantity}</p>
                  <button
                    onClick={() => deleteProductFromCart(item.code)}
                    className={styles.removeButton}
                  >
                    Eliminar
                  </button>
                </div>
              ) : null;
            })
          )}
        </div>
        <div className={styles.total}>
          <h3>Total del carrito: ${total}</h3>
        </div>
      </div>
    </div>
  );
};

export default NewCartModal;
