// NewHeader.tsx
import React from "react";

interface NewHeaderProps {
  setShowCartResume: React.Dispatch<React.SetStateAction<boolean>>;
  itemQuantity: number;
}

const NewHeader: React.FC<NewHeaderProps> = ({ setShowCartResume, itemQuantity }) => {
  return (
    <header>
      <button onClick={() => setShowCartResume(true)}>Ver carrito</button>
      <div>Cantidad de productos: {itemQuantity}</div>
    </header>
  );
};

export default NewHeader;
